import unittest
from main import div_number


# Четыре категории юнит-тестов (может быть больше и меньше)
# 1) Базовые случаи. Те ситуации, в которых наш код чувствует себя комфортно.
# Стандартные ситуации.
# 2) Пограничные ситуации. Когда наш код работает, но в этих местах может быть
# потенциальная ошибка.
# 3) Большие значения. Проверка на больших данных (но в рамках задачи).
# 4) Заведомо ошибочные. Код не должен работать в этих ситуациях.


class TestDivNumber(unittest.TestCase):
    def test_base(self):
        self.assertEqual(div_number(5, 5), 1)
        self.assertEqual(div_number(-10, 5), -2)
        self.assertEqual(div_number(10, -5), -2)
        self.assertEqual(div_number(-10, -5), 2)

    def test_borderline(self):
        self.assertEqual(div_number(10.5, 2), 5.25)
        self.assertEqual(div_number(10.000000, 1.00), 10)

    def test_big_number(self):
        self.assertEqual(div_number(1_000_000_000_000, 5), 200_000_000_000)
        self.assertEqual(div_number(-1_000_000_000_000, 5), -200_000_000_000)
        self.assertEqual(div_number(1_000_000_000_000, 1_000_000), 1_000_000)

    def test_error(self):
        self.assertRaises(ZeroDivisionError, div_number, 1, 0)
        self.assertRaises(TypeError, div_number, '1', 1)
        self.assertRaises(TypeError, div_number, 1, [9])

        # Эта ошибка возможно только в теории, но не в реальной жизни.
        # Такие ситуации мы не тестируем
